// Check the shared secret, then turn the raw event into an alert.
const secret = $env.FOODSPHERE_N8N_SECRET;
return $input.all().map((item) => {
  const headers = item.json.headers || {};
  if (!secret || headers['x-foodsphere-secret'] !== secret) {
    throw new Error('Rejected: missing or wrong x-foodsphere-secret header');
  }
  const e = item.json.body || {};
  const d = e.data || {};
  const deadline = d.safe_until ? new Date(d.safe_until).toLocaleString('en-GB', { timeZone: 'Asia/Dhaka', dateStyle: 'medium', timeStyle: 'short' }) : 'soon';
  const templates = {
    'donation.deadline_soon': ['Donation about to expire', `${d.item_name} (${d.quantity} ${d.unit}, ${d.area || 'Dhaka'}) must be collected before ${deadline}. Current status: ${d.status}.`, true],
    'donation.expired': ['Donation expired', `${d.item_name} expired before collection: ${d.quantity} ${d.unit} of ${d.food_category} was lost.`, true],
    'collection.failed': ['Collection failed', `Pickup of ${d.item_name} (${d.quantity} ${d.unit}) failed. Reason: ${d.reason}.`, true],
    'donation.created': ['New donation listed', `${d.item_name} (${d.quantity} ${d.unit}) is available in ${d.area || 'Dhaka'} with ${d.eligible_recipients ?? 0} eligible recipients.`, false],
    'donation.delivered': ['Donation delivered', `${d.quantity_delivered} ${d.unit} of ${d.item_name} was delivered.`, false],
    'automation.test': ['n8n connection test', `FoodSphere AI reached n8n and n8n reached FoodSphere AI (requested by ${d.requested_by || 'an administrator'}).`, true],
  };
  const [title, message, urgent] = templates[e.event] || ['FoodSphere event', `Unhandled event: ${e.event}`, false];
  return {
    json: {
      event: e.event,
      urgent,
      occurredAt: e.occurredAt,
      alert: { event: e.event, title, message, link: d.id ? `/app/donations/${d.id}` : '/app/admin', donationId: d.id ?? null },
    },
  };
});
